import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 16 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each (147 items total). Passages, prompts,
 * and numbers are distinct from earlier practice tests.
 */

// ─────────────────────── PRACTICE TEST 16 · R&W M1 (27) ──────────────────────
const T16_RW_M1: SatQuestion[] = [
  { id: "t16rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The lecture was so ______ that students who had dreaded the topic left eager to read more about it on their own.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["engaging", "tedious", "incoherent", "brief"], correct: 0, explanation: "The answer is \"engaging.\" The clause \"students who had dreaded the topic left eager to read more\" describes a reversal from dread to enthusiasm, which only a captivating, interest-sparking lecture would produce. \"Tedious\" (boring) would leave students still dreading the topic, the opposite effect. \"Incoherent\" (confusing, disjointed) would frustrate students, not inspire further reading. \"Brief\" merely describes the lecture's length and gives no reason students became eager to learn more." },
  { id: "t16rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee ______ reviewing the budget proposals all afternoon before reaching a decision.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "are", "have been"], correct: 0, explanation: "The answer is \"was.\" This tests subject-verb agreement and verb tense: \"committee\" is a singular collective noun treated as a single unit, and the time marker \"all afternoon before reaching a decision\" places the action in the simple past, so the singular past \"was\" is correct. \"Were\" is the plural past form and disagrees with the singular subject. \"Are\" is plural and present tense, wrong on both number and time. \"Have been\" is present-perfect, implying an action continuing into the present, which clashes with the clearly completed past event." },
  { id: "t16rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Certain desert plants open their pores only at night, taking in carbon dioxide in the cool dark and storing it for daytime photosynthesis, which sharply limits the water they lose to the sun.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["A nighttime gas-exchange strategy lets these plants photosynthesize by day while conserving water.", "These plants cannot photosynthesize at all.", "These plants lose more water than ordinary plants.", "These plants open their pores only during the hottest hours."], correct: 0, explanation: "The answer is choice A. The passage's main idea is that these desert plants take in carbon dioxide at night and store it so they can photosynthesize during the day while losing little water to the sun; choice A captures exactly this trade-off (a nighttime gas-exchange strategy that conserves water yet still allows daytime photosynthesis). Choice B (\"cannot photosynthesize at all\") contradicts the text, which explicitly says the stored CO2 is used \"for daytime photosynthesis.\" Choice C (\"lose more water than ordinary plants\") reverses the text, which states the strategy \"sharply limits the water they lose.\" Choice D (\"open their pores only during the hottest hours\") flips the stated timing: the plants open their pores \"only at night,\" in \"the cool dark,\" not during the hot daytime." },
  { id: "t16rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail was washed out by the spring floods. ______, the rangers closed it until repairs could be made.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Therefore", "However", "In contrast"], correct: 1, explanation: "The answer is \"Therefore.\" The first sentence states a cause (the trail was washed out by floods) and the second states its consequence (the rangers closed it), so a cause-and-effect transition is required, and \"Therefore\" signals exactly that result relationship. \"Nevertheless\" and \"However\" both signal contrast or concession, but there is no opposition here — closing a damaged trail follows naturally from the damage. \"In contrast\" also marks a difference between two ideas, yet the two sentences agree rather than conflict, so it misrepresents the logic." },
  { id: "t16rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The tour visits three capitals ______ Rome, Vienna, and Prague.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["capitals, ", "capitals: ", "capitals; ", "capitals "], correct: 1, explanation: "The answer is \"capitals: \" with a colon. The rule: a colon is used after a complete independent clause to introduce a list, explanation, or example. \"The tour visits three capitals\" is a complete clause, and \"Rome, Vienna, and Prague\" is the list naming those capitals, so the colon is correct. The comma (\"capitals, \") is too weak a mark to formally introduce the list and would read as a loose appositive. The semicolon (\"capitals; \") must join two independent clauses, but \"Rome, Vienna, and Prague\" is not a clause. No punctuation (\"capitals \") runs the list into the sentence without the signal a formal list requires." },
  { id: "t16rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The committee's report was admirably ______, addressing every objection raised in the public hearings point by point.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["comprehensive", "evasive", "rushed", "vague"], correct: 0, explanation: "The answer is \"comprehensive.\" The detail \"addressing every objection raised in the public hearings point by point\" describes total, thorough coverage, and \"admirably\" signals the word is a compliment; \"comprehensive\" means complete and all-inclusive, matching both. \"Evasive\" means dodging or avoiding the issues, the opposite of addressing every objection. \"Vague\" means unclear and imprecise, which also contradicts the point-by-point thoroughness being praised. \"Rushed\" describes the pace or haste of the work, not its completeness, and carries a negative tone that clashes with \"admirably.\"" },
  { id: "t16rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is awarded only to writers who have published at least one book and who are under the age of thirty-five.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A thirty-year-old who has published two books may qualify.", "A writer who has never published a book may qualify.", "Any writer over thirty-five may qualify.", "Only writers with no books may qualify."], correct: 0, explanation: "The answer is choice A. The text sets two requirements joined by \"and\": the writer must have published at least one book AND be under thirty-five. A thirty-year-old who has published two books satisfies both (two books meets \"at least one,\" and thirty is under thirty-five). Choice B (a writer who has never published) fails the publication requirement. Choice C (any writer over thirty-five) fails the age cap, since the fellowship is for those under thirty-five. Choice D (only writers with no books) directly contradicts the requirement to have published at least one book." },
  { id: "t16rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum redesigned its exhibits to be more accessible. ______, it added audio guides in six languages.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "For example", "Otherwise", "Instead"], correct: 1, explanation: "The answer is \"For example.\" The first sentence makes a general claim (the museum redesigned its exhibits to be more accessible) and the second gives one specific instance of that effort (audio guides in six languages), so an illustration transition is needed. \"For example\" introduces exactly such a supporting instance. \"However\" signals contrast, but the audio guides support rather than oppose the accessibility goal. \"Otherwise\" introduces an alternative or consequence of not doing something, which does not fit. \"Instead\" signals substitution — replacing one thing with another — but the audio guides add to the redesign rather than replace it." },
  { id: "t16rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the memoir refreshingly ______, free of the self-flattery that fills so many accounts by public figures.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["candid", "boastful", "guarded", "dull"], correct: 0, explanation: "The answer is \"candid.\" The phrase \"free of the self-flattery that fills so many accounts by public figures\" tells us the memoir is frank and unflattering about its author; \"candid\" means openly honest and straightforward, which fits, and \"refreshingly\" marks it as a welcome quality. \"Boastful\" means full of self-praise — precisely the self-flattery the memoir is said to lack. \"Guarded\" means cautious and reserved, but a guarded memoir would hold back, not offer the open honesty implied. \"Dull\" means boring and would not be described as \"refreshingly,\" nor does it relate to the absence of self-flattery." },
  { id: "t16rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Honeybees communicate the location of food by performing a looping \"waggle dance\" whose angle and duration encode the direction and distance other bees must fly.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Honeybees use a dance to tell hive-mates where food is located.", "Honeybees cannot share information with one another.", "Honeybees fly in random directions to find food.", "The waggle dance has no meaning."], correct: 0, explanation: "The answer is choice A. The passage's main idea is that honeybees use the \"waggle dance,\" whose angle and duration \"encode the direction and distance other bees must fly,\" to tell hive-mates where food is; choice A restates this communication of food location. Choice B (\"cannot share information\") contradicts the text, which describes the dance as a means of sharing exactly that information. Choice C (\"fly in random directions\") contradicts the passage, since the dance gives a precise direction and distance. Choice D (\"the dance has no meaning\") contradicts the claim that the dance encodes specific information." },
  { id: "t16rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the coach nor the players ______ satisfied with the referee's final call.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "The answer is \"were.\" The rule of proximity for \"neither…nor\" (and \"either…or\") subjects: the verb agrees in number with the noun nearer to it. Here the nearer noun is the plural \"players,\" so the plural verb \"were\" is required, and the past tense suits the completed reaction to the final call. \"Was\" is singular and would only fit if the nearer noun were singular. \"Is\" is singular and also present tense, wrong on both number and time. \"Has been\" is singular present-perfect, mismatching the plural \"players\" and the simple past context." },
  { id: "t16rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The new bridge cost far more than planned. ______, it cut the average commute across the river nearly in half.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "The answer is \"Still.\" The first sentence states a drawback (the bridge cost far more than planned) and the second states a benefit despite that drawback (it nearly halved the commute), so a concessive contrast transition is needed. \"Still\" means \"even so\" and signals that the benefit holds despite the cost. \"Therefore\" implies the benefit was caused by the high cost, which is illogical. \"For instance\" introduces an example, but the commute time is not an example of the cost overrun. \"In short\" signals a summary, yet the second sentence adds new contrasting information rather than restating the first." },
  { id: "t16rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Average rainfall measured 22 inches in the eastern county, 31 inches in the central county, and 18 inches in the western county last year.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The western county received the least rainfall.", "The eastern county received the most rainfall.", "The central county received the least rainfall.", "All three counties received equal rainfall."], correct: 0, explanation: "The answer is choice A. Compare the three figures given: eastern 22 inches, central 31 inches, western 18 inches. The smallest value is 18 inches, the western county, so it received the least rainfall — exactly what choice A states. Choice B is wrong because the eastern county's 22 inches is not the largest; the central county's 31 inches is. Choice C is wrong because the central county at 31 inches received the most, not the least. Choice D is wrong because 22, 31, and 18 are three different values, so the totals are not equal." },
  { id: "t16rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The scientist published a study ______ overturned a long-held assumption about coral growth.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The answer is \"that.\" The rule: a relative clause modifying a noun (the antecedent \"study\") is introduced by a relative pronoun such as \"that\" or \"which,\" and \"that\" correctly links \"study\" to the clause \"overturned a long-held assumption.\" \"What\" is a relative pronoun that cannot take a noun antecedent; it stands in for the thing itself (\"what overturned…\"), so it cannot follow \"study.\" \"Where\" introduces clauses about a place or location, but a study is not a place. \"And it\" turns the modifier into a second independent clause without proper joining, creating a run-on/comma-splice-style fault." },
  { id: "t16rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Rushing to catch the train, ______ the briefcase was left behind on the platform bench.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["rushing to catch the train, the briefcase was left behind", "the traveler, rushing to catch the train, left the briefcase behind", "the platform bench held the briefcase, rushing to catch the train", "left behind, the train was caught by the briefcase"], correct: 1, explanation: "The answer is choice B. The rule: an introductory participial phrase (\"Rushing to catch the train\") must modify the noun that immediately follows it, and logically only a person can rush to catch a train. Choice B places \"the traveler\" right after the phrase, so the traveler does the rushing — correct. Choice A leaves \"the briefcase\" as the subject, illogically making the briefcase rush to catch the train (a dangling modifier). Choice C makes \"the platform bench\" the thing rushing, equally illogical. Choice D scrambles the meaning entirely, having \"the train\" caught \"by the briefcase,\" which is nonsensical and still mismatches the modifier." },
  { id: "t16rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist argues that offering free public transit increases overall productivity because workers spend less time and money commuting.", prompt: "Which finding, if true, would most strengthen the economist's claim?", type: "mcq", choices: ["Cities that made transit free saw measurable gains in worker output.", "Free transit is popular among residents.", "Building new transit lines is expensive.", "Most commuters already own cars."], correct: 0, explanation: "The answer is choice A. The economist's claim is that free public transit increases overall productivity. To strengthen it, we need evidence linking free transit to higher productivity, and choice A provides exactly that: cities that made transit free \"saw measurable gains in worker output,\" which is a direct measure of productivity. Choice B (free transit is popular) shows approval but says nothing about productivity. Choice C (building transit lines is expensive) concerns cost, which is irrelevant to and even slightly weakens the case. Choice D (most commuters already own cars) is unrelated to whether free transit raises output." },
  { id: "t16rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with the lead actors, ______ planning a surprise for opening night.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The answer is \"is.\" The rule: a phrase introduced by \"together with,\" \"along with,\" \"as well as,\" or \"in addition to\" is parenthetical and does not change the number of the subject. The true subject is the singular \"director,\" so it takes the singular verb \"is,\" and present tense fits the ongoing planning. \"Are\" and \"were\" are plural and wrongly agree with \"actors,\" the noun inside the interrupting phrase, not the subject. \"Have been\" is plural present-perfect and likewise fails to agree with the singular \"director.\"" },
  { id: "t16rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to stress that an unexpected result held up under repeated testing. ______, the effect appeared in all five follow-up trials.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Indeed", "However", "Otherwise"], correct: 1, explanation: "The answer is \"Indeed.\" The researcher wants to stress that the unexpected result was reliable, and the second sentence reinforces this by noting the effect \"appeared in all five follow-up trials\"; \"Indeed\" is an intensifier that emphasizes and confirms the preceding point, which matches. \"By contrast\" signals opposition, but the second sentence supports rather than opposes the claim of reliability. \"However\" likewise marks a contrast that is not present. \"Otherwise\" introduces an alternative scenario or consequence, but no alternative is being offered — the sentence adds confirming evidence." },
  { id: "t16rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The novel's narrator is deliberately ______: readers can never be sure whether his confident account of events should be trusted.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unreliable", "omniscient", "transparent", "honest"], correct: 0, explanation: "The answer is \"unreliable.\" The colon expands the blank: \"readers can never be sure whether his confident account of events should be trusted\" defines a narrator whose word cannot be taken at face value, which is precisely an \"unreliable\" narrator. \"Omniscient\" describes a narrator who knows everything about the story, a matter of knowledge, not of whether readers can trust the account. \"Transparent\" means clear and easy to see through, implying the narrator hides nothing — the opposite of the doubt described. \"Honest\" directly contradicts the inability to trust the narrator's account." },
  { id: "t16rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is open only to students who major in engineering and who maintain a grade average above 3.5.", prompt: "Which student clearly qualifies for the scholarship?", type: "mcq", choices: ["An engineering major with a 3.8 average.", "A history major with a 3.9 average.", "An engineering major with a 3.0 average.", "A student with no declared major."], correct: 0, explanation: "The answer is choice A. The scholarship requires two conditions joined by \"and\": the student must major in engineering AND keep an average above 3.5. Choice A (engineering major, 3.8) meets both. Choice B (history major, 3.9) fails the major requirement even though the grade is high. Choice C (engineering major, 3.0) fails the grade requirement, since 3.0 is not above 3.5. Choice D (no declared major) fails the major requirement and gives no grade, so it cannot qualify." },
  { id: "t16rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the engine ______ they refueled the aircraft for its next flight.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["engine, and then", "engine and, then", "engine then", "engine, then"], correct: 0, explanation: "The answer is \"engine, and then.\" The rule: two independent clauses (\"The crew repaired the engine\" and \"they refueled the aircraft…\") are joined by a comma plus a coordinating conjunction (here \"and\"); \"then\" is an adverb that follows the conjunction. \"Engine and, then\" misplaces the comma after \"and,\" which is never correct. \"Engine then\" joins the two clauses with only the adverb \"then\" and no conjunction, creating a run-on. \"Engine, then\" joins two independent clauses with a comma and the adverb \"then\" alone, producing a comma splice because \"then\" is not a coordinating conjunction." },
  { id: "t16rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although famous for his ______ public speeches, the philosopher wrote private letters that were warm and almost playful.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["austere", "tender", "casual", "humorous"], correct: 0, explanation: "The answer is \"austere.\" The word \"Although\" sets up a contrast between the public speeches and the private letters, which are \"warm and almost playful\"; the speeches must therefore be the opposite in tone, and \"austere\" (severe, stern, plain) provides that contrast. \"Tender\" means gentle and affectionate, which matches the letters rather than contrasting with them. \"Casual\" means relaxed and informal, again similar to \"playful,\" so no contrast. \"Humorous\" means funny, which overlaps with \"playful\" and fails to create the opposition \"Although\" demands." },
  { id: "t16rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A geographer notes that coastal cities founded near natural harbors grew into major trade hubs faster than inland settlements, crediting the ease of shipping goods by sea.", prompt: "Which choice best describes the geographer's explanation?", type: "mcq", choices: ["Harbor access made sea shipping easy, speeding the growth of coastal cities.", "Inland settlements had better access to shipping.", "Natural harbors slowed the growth of nearby cities.", "City location had no effect on trade."], correct: 0, explanation: "The answer is choice A. The geographer's explanation is that coastal cities near natural harbors grew into trade hubs faster than inland settlements because harbors made \"shipping goods by sea\" easy; choice A captures this cause (easy sea shipping) and effect (faster growth of coastal cities). Choice B reverses the advantage by giving inland settlements better shipping access, contradicting the text. Choice C says harbors slowed growth, the opposite of \"grew…faster.\" Choice D denies any effect of location, contradicting the geographer's whole point that harbor access drove faster growth." },
  { id: "t16rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The library extended its hours ______ many students had asked for more time to study before exams.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["hours because", "hours, because", "hours; because", "hours: because"], correct: 0, explanation: "The answer is \"hours because.\" The rule: when a subordinate \"because\" clause follows the main clause and gives essential cause, no comma is needed before \"because,\" so \"hours because\" correctly joins the reason to the main clause. \"Hours, because\" inserts an unnecessary comma before an essential subordinate clause. \"Hours; because\" misuses a semicolon, which must join two independent clauses, but \"because many students had asked…\" is a dependent clause. \"Hours: because\" misuses a colon, which introduces a list or explanation after a complete clause but is wrong before a subordinating conjunction like \"because.\"" },
  { id: "t16rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The company switched its delivery fleet to electric vehicles. ______, it lowered its fuel costs and its carbon emissions at once.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The answer is \"As a result.\" The first sentence states an action (switching the fleet to electric vehicles) and the second states its consequence (lower fuel costs and emissions), so a cause-effect transition is needed, and \"As a result\" signals that the second sentence is the outcome of the first. \"Nevertheless\" signals contrast, but the lower costs agree with, not oppose, the switch. \"For example\" introduces an illustration, yet the cost savings are a result, not an example of the switch. \"On the other hand\" sets up an opposing point, which the supporting consequence does not provide." },
  { id: "t16rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach offered ______ feedback, pointing out exactly which footwork drill each player should practice next.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "general", "vague", "harsh"], correct: 0, explanation: "The answer is \"specific.\" The detail \"pointing out exactly which footwork drill each player should practice next\" describes precise, targeted feedback, and \"specific\" means clearly defined and particular, matching exactly. \"General\" means broad and non-specific, the opposite of pointing out exactly which drill. \"Vague\" means unclear and imprecise, also contradicting the exactness described. \"Harsh\" describes a severe tone, but the sentence emphasizes precision, not severity, so it misses the point." },
  { id: "t16rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "After beavers returned to the stream, their dams slowed the current, which let sediment settle and created wetland pools that, in turn, drew back frogs and wading birds that had long been absent.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Returning beavers set off a chain of changes that revived wetland wildlife.", "Beavers drove away all wildlife from the stream.", "The dams sped up the stream's current.", "Frogs and birds had always lived at the stream."], correct: 0, explanation: "The answer is choice A. The passage traces a sequence: beavers returned, their dams slowed the current, which let sediment settle and form wetland pools, which in turn drew back frogs and wading birds that had been absent — a chain of changes that revived wetland wildlife, as choice A states. Choice B (drove away all wildlife) contradicts the text, which says wildlife was drawn back. Choice C (sped up the current) contradicts \"slowed the current.\" Choice D (frogs and birds had always lived there) contradicts \"had long been absent.\"" },
];

// ─────────────────────── PRACTICE TEST 16 · R&W M2 easy (27) ─────────────────
const T16_RW_M2E: SatQuestion[] = [
  { id: "t16rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was too ______ to carry, so she took out half of her books.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "empty", "small"], correct: 0, explanation: "The answer is \"heavy.\" The clue \"too ______ to carry, so she took out half of her books\" shows weight was the problem, and removing books lightens a heavy load. \"Light\" is the opposite — a light backpack carries easily, giving no reason to remove anything. \"Empty\" contradicts the fact that it still held books to take out. \"Small\" describes size, but a small pack would not be hard to carry, so it does not fit the weight clue." },
  { id: "t16rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are.\" Subject-verb agreement requires a plural verb for the plural subject \"three puppies,\" and \"are\" is the plural present-tense form that pairs with \"playing.\" \"Is\" is singular present and cannot follow a plural subject. \"Was\" is singular past, wrong in both number and tense for an ongoing action. \"Am\" is the first-person singular form used only with \"I,\" so it cannot match \"puppies.\"" },
  { id: "t16rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bats are not blind; they use sound that bounces off objects to find their way and catch insects in the dark.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bats use bouncing sound to navigate and hunt in the dark.", "Bats cannot move at night.", "Bats are completely blind.", "Bats never eat insects."], correct: 0, explanation: "The answer is \"Bats use bouncing sound to navigate and hunt in the dark,\" which restates the passage's claim that bats \"use sound that bounces off objects to find their way and catch insects in the dark.\" \"Bats cannot move at night\" contradicts \"find their way,\" which shows they do move. \"Bats are completely blind\" directly contradicts the opening clause \"Bats are not blind.\" \"Bats never eat insects\" contradicts \"catch insects in the dark.\"" },
  { id: "t16rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "It began to rain hard. ______, we moved the picnic inside.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The answer is \"So.\" The hard rain is the cause and moving the picnic inside is its result, so the cause-effect connector \"So\" matches the logic. \"For example\" would signal that moving inside illustrates the rain, but it is a consequence, not an example. \"However\" signals contrast, yet the two sentences agree rather than oppose. \"Meanwhile\" marks simultaneous events, but the rain leads to the move rather than merely happening alongside it." },
  { id: "t16rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at my grandmother's house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "The answer is \"ate.\" The time marker \"Last night\" signals completed past action, and \"ate\" is the simple past tense of \"eat,\" which also agrees with the subject \"we.\" \"Eat\" is present tense and clashes with \"last night.\" \"Eats\" is the third-person singular present form, wrong in both tense and number for \"we.\" \"Eating\" is a participle that needs a helping verb (such as \"were\") and cannot serve as the main verb on its own." },
  { id: "t16rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puzzle was very ______, so it took us all weekend to finish.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["difficult", "simple", "small", "colorful"], correct: 0, explanation: "The answer is \"difficult.\" The clue \"so it took us all weekend to finish\" shows the puzzle resisted quick solving, which a difficult puzzle does. \"Simple\" is the opposite — a simple puzzle would be finished fast, not over a whole weekend. \"Small\" describes size and would suggest a quick job, not a long one. \"Colorful\" describes appearance and has no bearing on how long the puzzle took." },
  { id: "t16rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives you exercise, and produces no pollution.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is harmful.", "Walking to school costs a lot of money.", "Walking to school causes pollution."], correct: 0, explanation: "The answer is \"Walking to school has several benefits.\" The sentence names three advantages — it \"saves money, gives you exercise, and produces no pollution\" — which \"several benefits\" accurately summarizes. \"Walking to school is harmful\" contradicts the positive list. \"Walking to school costs a lot of money\" contradicts \"saves money.\" \"Walking to school causes pollution\" contradicts \"produces no pollution.\"" },
  { id: "t16rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "We waited nearly ______ hour for the doctor.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is \"an.\" The rule: use \"an\" before a word that begins with a vowel sound, not just a vowel letter. \"Hour\" starts with a silent h, so it begins with the vowel sound \"ow,\" requiring \"an.\" \"A\" is used before consonant sounds, so it does not fit the vowel sound of \"hour.\" \"The only\" would mean it was the single hour available, changing the meaning of \"nearly an hour.\" \"Some\" is vague and does not pair with the singular measured \"hour\" the sentence describes." },
  { id: "t16rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The water in the lake was so ______ that we could see the rocks at the bottom.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "muddy", "deep", "cold"], correct: 0, explanation: "The answer is \"clear.\" The clue \"so ______ that we could see the rocks at the bottom\" shows the water let light and sight pass through, which describes \"clear\" water. \"Muddy\" water is cloudy and would hide the rocks, the opposite effect. \"Deep\" describes how far down the water goes, not how transparent it is, and deep water can be murky. \"Cold\" describes temperature, which has nothing to do with whether you can see the bottom." },
  { id: "t16rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and I ______ baking cookies this afternoon.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are.\" The rule: a compound subject joined by \"and\" (\"my sister and I\") is plural and takes a plural verb, so \"are\" is correct, and present tense fits the action happening \"this afternoon.\" \"Is\" is singular present and cannot follow a plural subject. \"Was\" is singular past, wrong in both number and tense. \"Am\" is the first-person singular form used only with \"I\" alone, so it cannot match the plural \"my sister and I.\"" },
  { id: "t16rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Trees take in carbon dioxide and release oxygen, which helps keep the air clean for people and animals.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Trees help clean the air by exchanging gases.", "Trees release carbon dioxide into the air.", "Trees make the air dirty.", "Trees have no effect on the air."], correct: 0, explanation: "The answer is choice A. The passage's main idea is that trees \"take in carbon dioxide and release oxygen, which helps keep the air clean,\" and choice A restates this gas exchange that cleans the air. Choice B (\"release carbon dioxide\") reverses the gases — trees take carbon dioxide in, not out. Choice C (\"make the air dirty\") contradicts \"helps keep the air clean.\" Choice D (\"no effect on the air\") contradicts the text, which describes a clear cleaning effect." },
  { id: "t16rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, we lit candles and waited it out.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "So", "For example", "Instead"], correct: 1, explanation: "The answer is \"So.\" The first sentence states a cause (the power went out) and the second states its result (we lit candles and waited it out), so the cause-effect connector \"So\" fits. \"However\" signals contrast, but lighting candles agrees with rather than opposes losing power. \"For example\" introduces an illustration, yet lighting candles is a response, not an example of the outage. \"Instead\" signals substitution of one action for another, but no alternative is being rejected here." },
  { id: "t16rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the chef ______ a new dessert for the menu.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["create", "creates", "created", "creating"], correct: 2, explanation: "The answer is \"created.\" The time marker \"Yesterday\" signals completed past action, so the simple past \"created\" is required, and it agrees with the singular subject \"the chef.\" \"Create\" is present tense (and plural form), clashing with \"yesterday.\" \"Creates\" is third-person singular present, correct in number but wrong in tense for a past event. \"Creating\" is a present participle that needs a helping verb (such as \"was\") and cannot stand alone as the sentence's main verb." },
  { id: "t16rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After the long hike, the campers were ______ and fell asleep quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "excited", "hungry", "curious"], correct: 0, explanation: "The answer is \"tired.\" The clue \"After the long hike\" and \"fell asleep quickly\" show the campers were worn out, which is what \"tired\" means. \"Excited\" describes high energy that would keep someone awake, the opposite of falling asleep quickly. \"Curious\" describes eager interest, which also would not lead to quick sleep. \"Hungry\" describes a need for food and does not explain why the campers fell asleep right away." },
  { id: "t16rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The bakery opens at 7 a.m. on weekdays but does not open until 9 a.m. on Saturdays.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The bakery opens later on Saturdays than on weekdays.", "The bakery never opens on weekdays.", "The bakery opens at midnight on Saturdays.", "The bakery is closed every Saturday."], correct: 0, explanation: "The answer is choice A. The text gives two opening times: 7 a.m. on weekdays and 9 a.m. on Saturdays. Since 9 a.m. is later than 7 a.m., the bakery opens later on Saturdays than on weekdays, exactly what choice A states. Choice B (\"never opens on weekdays\") contradicts the stated 7 a.m. weekday opening. Choice C (\"opens at midnight on Saturdays\") contradicts the stated 9 a.m. Saturday time. Choice D (\"closed every Saturday\") contradicts the text, which says it opens at 9 a.m. on Saturdays." },
  { id: "t16rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The bird built ______ nest in the old oak tree.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The answer is \"its.\" The rule: \"its\" is the singular possessive pronoun (showing ownership) and matches the singular subject \"The bird,\" so \"its nest\" correctly shows the nest belongs to the bird. \"It's\" is a contraction of \"it is\" and would wrongly read \"the bird built it is nest.\" \"Their\" is a plural possessive and does not agree with the singular \"bird.\" \"They're\" is a contraction of \"they are,\" both plural and not possessive, so it fits neither the number nor the possessive need." },
  { id: "t16rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals sleep through the winter. ______, bears spend the cold months in a deep rest.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is \"For example.\" The first sentence makes a general claim (some animals sleep through the winter) and the second gives a specific case (bears spend the cold months in deep rest), so an illustration transition is needed, and \"For example\" introduces exactly such a supporting case. \"However\" signals contrast, but bears support rather than oppose the general claim. \"Instead\" signals substitution, yet nothing is being replaced. \"Otherwise\" introduces an alternative or consequence, which does not fit a supporting example." },
  { id: "t16rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The street was very ______, so we had to shout to hear each other.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["noisy", "quiet", "empty", "narrow"], correct: 0, explanation: "The answer is \"noisy.\" The clue \"so ______ that we had to shout to hear each other\" shows there was loud background sound drowning out voices, which describes a \"noisy\" street. \"Quiet\" is the opposite — on a quiet street there would be no need to shout. \"Empty\" describes a lack of people and would also be quiet, giving no reason to shout. \"Narrow\" describes the street's width, which has nothing to do with how loud it is." },
  { id: "t16rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The keys ______ on the kitchen counter where I left them.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are.\" Subject-verb agreement requires a plural verb for the plural subject \"The keys,\" so \"are\" is correct, and present tense fits the keys' current location. \"Is\" is singular present and cannot follow a plural subject. \"Was\" is singular past, wrong in both number and tense. \"Am\" is the first-person singular form used only with \"I,\" so it cannot match \"keys.\"" },
  { id: "t16rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Some lizards can drop their tails to escape a predator, and the tail later grows back.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Some lizards can lose and regrow their tails.", "Lizards cannot escape predators.", "Lizards never lose their tails.", "A lizard's tail never grows back."], correct: 0, explanation: "The answer is choice A. The passage's main idea is that some lizards \"can drop their tails to escape a predator, and the tail later grows back,\" which choice A restates as losing and regrowing their tails. Choice B (\"cannot escape predators\") contradicts the text, since dropping the tail is exactly how they escape. Choice C (\"never lose their tails\") contradicts \"can drop their tails.\" Choice D (\"a lizard's tail never grows back\") contradicts \"the tail later grows back.\"" },
  { id: "t16rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to hike the long trail. ______, the rain forced us to take the short one.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The answer is \"However.\" The first sentence states a plan (to hike the long trail) and the second states an outcome that thwarts it (the rain forced the short one), so a contrast transition is needed, and \"However\" signals that the result went against the plan. \"Therefore\" signals cause-effect, implying the short trail was the planned result, which is wrong. \"Similarly\" signals likeness, but the two ideas oppose rather than match. \"For example\" introduces an illustration, yet the second sentence reverses the plan rather than illustrating it." },
  { id: "t16rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month our class ______ to perform a short play.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The answer is \"plans.\" The rule: a collective noun like \"class\" acting as a single unit is singular and takes the singular verb \"plans,\" and the simple present is acceptable for a scheduled future event signaled by \"Next month.\" \"Plan\" is the plural/base form and does not agree with the singular \"class.\" \"Planned\" is past tense, clashing with the future \"next month.\" \"Planning\" is a participle that needs a helping verb (such as \"is\") and cannot serve as the main verb alone." },
  { id: "t16rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new tablet is very ______; it can run for two days on a single charge.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["efficient", "fragile", "expensive", "heavy"], correct: 0, explanation: "The answer is \"efficient.\" The clue \"it can run for two days on a single charge\" shows the tablet makes excellent use of its power, which is what \"efficient\" means. \"Fragile\" means easily broken and says nothing about battery life. \"Expensive\" describes cost, not how long the charge lasts. \"Heavy\" describes weight, again unrelated to running two days on one charge." },
  { id: "t16rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Stretching before exercise warms up the muscles, improves flexibility, and lowers the risk of injury.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Stretching before exercise provides several benefits.", "Stretching causes more injuries.", "Stretching makes muscles colder.", "Stretching should never be done."], correct: 0, explanation: "The answer is choice A. The sentence lists three advantages of stretching before exercise — it \"warms up the muscles, improves flexibility, and lowers the risk of injury\" — which choice A accurately summarizes as \"several benefits.\" Choice B (\"causes more injuries\") contradicts \"lowers the risk of injury.\" Choice C (\"makes muscles colder\") contradicts \"warms up the muscles.\" Choice D (\"should never be done\") contradicts the whole positive list of benefits." },
  { id: "t16rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She picked ______ apple from the basket on the table.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is \"an.\" The rule: use \"an\" before a word beginning with a vowel sound, and \"apple\" starts with the vowel sound \"a,\" so \"an apple\" is correct. \"A\" is used before consonant sounds and does not fit the vowel sound of \"apple.\" \"The only\" would mean it was the single apple in the basket, changing the meaning. \"Some\" is used for plural or uncountable nouns and does not pair with the singular \"apple\" she picked." },
  { id: "t16rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were easy to follow. ______, the bookshelf went together in under an hour.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is \"As a result.\" The first sentence states a cause (the directions were easy to follow) and the second states its consequence (the bookshelf went together in under an hour), so a cause-effect transition is needed, and \"As a result\" signals that outcome. \"However\" signals contrast, but quick assembly agrees with easy directions. \"Instead\" signals substitution, yet nothing is being replaced. \"Otherwise\" suggests what would happen under different conditions, which does not match the direct consequence described." },
  { id: "t16rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience grew ______ as the magician revealed his final, surprising trick.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "The answer is \"amazed.\" The clue \"as the magician revealed his final, surprising trick\" calls for the natural delighted reaction to a surprise, which is to be \"amazed.\" \"Bored\" describes disinterest, the opposite of being captivated by a surprising trick. \"Sleepy\" describes drowsiness, also at odds with an exciting reveal. \"Angry\" describes displeasure, which does not fit a delightful surprise meant to impress the audience." },
];

// ─────────────────────── PRACTICE TEST 16 · R&W M2 hard (27) ─────────────────
const T16_RW_M2H: SatQuestion[] = [
  { id: "t16rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The candidate's statement was carefully ______, praising the plan's goals while committing to none of its actual provisions.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["noncommittal", "decisive", "blunt", "enthusiastic"], correct: 0, explanation: "The answer is \"noncommittal.\" The detail \"praising the plan's goals while committing to none of its actual provisions\" describes a statement that sounds supportive but pledges nothing, which is exactly what \"noncommittal\" means. \"Decisive\" means firm and conclusive, the opposite of committing to nothing. \"Blunt\" means direct and outspoken, which a carefully evasive statement is not. \"Enthusiastic\" means eagerly positive and overstates a statement deliberately crafted to avoid commitment." },
  { id: "t16rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The article first lays out the conventional explanation in detail, then devotes its remaining pages to dismantling that explanation point by point.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It presents an accepted view and then systematically argues against it.", "It defends the conventional view throughout.", "It lists unrelated facts with no argument.", "It repeats a single example without analysis."], correct: 0, explanation: "The answer is choice A. The text describes a two-part structure: it \"first lays out the conventional explanation in detail,\" then \"devotes its remaining pages to dismantling that explanation point by point\" — that is, presenting an accepted view and then systematically arguing against it, exactly choice A. Choice B (\"defends the conventional view throughout\") reverses the author's stance, since the article attacks that view. Choice C (\"lists unrelated facts with no argument\") ignores the clear refuting argument. Choice D (\"repeats a single example without analysis\") contradicts the detailed, point-by-point dismantling described." },
  { id: "t16rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A coating retained 95% of its shine after 1 year, 93% after 2 years, and 70% after 5 years of outdoor exposure.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Shine declined far more steeply between years 2 and 5 than in the first two years.", "Shine increased over time.", "Shine stayed perfectly constant.", "The coating had no shine left after 2 years."], correct: 0, explanation: "The answer is choice A. Read the figures: shine was 95% at year 1, 93% at year 2, and 70% at year 5. From year 1 to year 2 it fell only 2 points (95 to 93), but from year 2 to year 5 it fell 23 points (93 to 70) over 3 years — far steeper, even per year (about 8 points/year versus 2 points/year). So the decline was much steeper between years 2 and 5, as choice A states. Choice B (\"increased over time\") contradicts the steadily falling numbers. Choice C (\"stayed perfectly constant\") contradicts the drop from 95% to 70%. Choice D (\"no shine left after 2 years\") misreads year 2, where 93% of the shine remained." },
  { id: "t16rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The medication relieved the patients' symptoms quickly. ______, it produced side effects severe enough that a third of them stopped taking it.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "The answer is \"However.\" The first sentence states a benefit (the medication relieved symptoms quickly) and the second states a serious drawback (side effects severe enough that a third of patients quit), so a contrast transition is needed, and \"However\" signals that opposition. \"Therefore\" implies the side effects resulted from the relief, which is illogical. \"Likewise\" signals similarity, but the two ideas conflict rather than match. \"Accordingly\" signals a consequence that follows logically, again implying agreement rather than the contrast present." },
  { id: "t16rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write reports, and ______ their findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "The answer is \"to present.\" The rule of parallel structure: items in a list must share the same grammatical form. The series here is \"to analyze data, to write reports, and ______ their findings,\" and the first two items are infinitives (\"to analyze,\" \"to write\"), so the third must also be the infinitive \"to present.\" \"Presenting\" is a gerund and breaks the infinitive parallel. \"Present\" is a bare verb form that omits the required \"to\" and disrupts the pattern. \"Presented\" is a past-tense/participle form that also breaks the parallel series." },
  { id: "t16rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The history refuses to ______ its central figure, presenting his cruelties as plainly as his reforms.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sanitize", "condemn", "describe", "recall"], correct: 0, explanation: "The answer is \"sanitize.\" The clue \"presenting his cruelties as plainly as his reforms\" shows the history does not soften or cover up its subject's faults; to \"sanitize\" means to clean up or make something appear more acceptable than it is, so refusing to sanitize fits perfectly. \"Condemn\" means to denounce, but refusing to condemn would mean refusing to criticize, the opposite of showing cruelties plainly. \"Describe\" is neutral and carries no sense of softening, so refusing to describe makes no sense with a book that presents the cruelties. \"Recall\" means to remember or mention, again lacking the favorable-cleanup sense the sentence rejects." },
  { id: "t16rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the earlier model treated emotions as obstacles to clear thinking, the newer account holds that emotions guide attention toward what matters and so aid reasoning.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older view of emotion with a newer, more favorable one.", "To prove emotions always cloud judgment.", "To summarize only the earlier model.", "To argue that reasoning is impossible."], correct: 0, explanation: "The answer is choice A. The construction \"Where the earlier model treated emotions as obstacles…the newer account holds that emotions…aid reasoning\" contrasts an older, negative view of emotion with a newer, more favorable one — exactly the purpose choice A names. Choice B (\"prove emotions always cloud judgment\") states the discarded older view as if it were the text's conclusion, ignoring the newer account. Choice C (\"summarize only the earlier model\") ignores the newer view that the text emphasizes. Choice D (\"argue reasoning is impossible\") is unsupported; the text says emotions can aid reasoning, not that reasoning is impossible." },
  { id: "t16rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The first prototype passed every safety test ______ the second prototype failed three of them on the first day.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["test, the", "test; the", "test the", "test: the"], correct: 1, explanation: "The answer is \"test; the\" with a semicolon. The rule: a semicolon joins two closely related independent clauses, and both \"The first prototype passed every safety test\" and \"the second prototype failed three of them on the first day\" are complete clauses, so the semicolon is correct. \"Test, the\" joins two independent clauses with only a comma, creating a comma splice. \"Test the\" runs the two clauses together with no punctuation, a run-on. \"Test: the\" misuses a colon, which introduces a list or explanation; here the second clause is a contrasting equal statement, not an elaboration of the first." },
  { id: "t16rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the lecture rewarded close attention, packing several intricate arguments into every few minutes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["simplistic", "demanding", "dense", "rigorous"], correct: 0, explanation: "The answer is \"simplistic.\" The phrase \"Far from being ______\" signals that the blank is the opposite of how the lecture is described, and since it \"rewarded close attention, packing several intricate arguments into every few minutes,\" the lecture is complex — so the word it is \"far from\" must mean the reverse, namely \"simplistic\" (oversimplified, lacking depth). \"Demanding\" means requiring effort, which describes the intricate lecture rather than opposing it. \"Dense\" means packed with content, again matching the lecture. \"Rigorous\" means thorough and exacting, which also fits the lecture rather than contrasting with it, so all three fail the \"far from\" reversal." },
  { id: "t16rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters insist the new schedule reduced worker fatigue without cutting output. Yet in the quarter it took effect, the factory's production fell by 6%.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It introduces evidence that complicates the supporters' claim.", "It restates the supporters' claim exactly.", "It confirms that output was unaffected.", "It proposes a different schedule."], correct: 0, explanation: "The answer is choice A. The first sentence gives the supporters' claim (the schedule reduced fatigue \"without cutting output\"), and the second sentence, signaled by \"Yet,\" reports that production \"fell by 6%\" — evidence that undercuts the claim of unaffected output, so its function is to complicate that claim, as choice A says. Choice B (\"restates the claim exactly\") is wrong because the second sentence opposes rather than repeats the claim. Choice C (\"confirms output was unaffected\") contradicts the 6% drop. Choice D (\"proposes a different schedule\") is wrong because the sentence offers data, not a new proposal." },
  { id: "t16rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The recipe demands three rare ingredients ______ saffron, truffle, and aged vinegar.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["ingredients,", "ingredients:", "ingredients;", "ingredients"], correct: 1, explanation: "The answer is \"ingredients:\" with a colon. The rule: a colon follows a complete independent clause to introduce a list, and \"The recipe demands three rare ingredients\" is complete, with \"saffron, truffle, and aged vinegar\" naming those ingredients. \"Ingredients,\" with a comma is too weak to formally introduce the list. \"Ingredients;\" with a semicolon is wrong because a semicolon joins two independent clauses, and the list is not a clause. \"Ingredients\" with no punctuation leaves the list unsignaled and runs it into the sentence." },
  { id: "t16rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The telescope captured the comet's approach in stunning detail. ______, clouds rolled in before it could record the closest pass.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Unfortunately", "Therefore", "Likewise"], correct: 1, explanation: "The answer is \"Unfortunately.\" The first sentence reports a success (the telescope captured the comet in stunning detail) and the second reports a setback (clouds rolled in before the closest pass), so a transition signaling a regrettable turn is needed, and \"Unfortunately\" fits. \"Indeed\" intensifies and confirms the prior point, but the clouds undercut rather than confirm the success. \"Likewise\" signals similarity, yet the two sentences contrast. \"Therefore\" implies the clouds resulted from the successful imaging, which is illogical." },
  { id: "t16rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, students who used the new study app scored 15% higher on the final exam, but they also reported spending 25% more time studying.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The app users scored higher but also studied more.", "The app users scored higher while studying less.", "The app had no effect on scores.", "Non-users scored higher than app users."], correct: 0, explanation: "The answer is choice A. The data state two facts: app users \"scored 15% higher\" AND \"reported spending 25% more time studying,\" so both their scores and their study time rose, exactly what choice A says. Choice B (\"scored higher while studying less\") reverses the study-time finding, which says they studied more, not less. Choice C (\"no effect on scores\") contradicts the 15% score gain. Choice D (\"non-users scored higher\") contradicts the finding that app users scored higher." },
  { id: "t16rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The sculpture that stands beside the fountains ______ to a sculptor whose later works fill the city's museums.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The answer is \"belongs.\" The rule: the verb agrees with the true subject, not with a noun in an intervening modifier. The subject is the singular \"The sculpture\"; \"that stands beside the fountains\" is a relative clause, and \"fountains\" is not the subject. A singular subject takes \"belongs.\" \"Belong\" is the plural form and wrongly agrees with \"fountains.\" \"Belonging\" is a participle that cannot serve as the main verb. \"To belong\" is an infinitive, which also cannot function as the sentence's main verb." },
  { id: "t16rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor was prized for her ______ — for cutting every sentence that did not earn its place on the page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["rigor", "leniency", "hesitation", "warmth"], correct: 0, explanation: "The answer is \"rigor.\" The dash expands the blank: \"cutting every sentence that did not earn its place on the page\" describes exacting, uncompromising standards, which is what \"rigor\" (strict thoroughness) means. \"Leniency\" means mildness or going easy, the opposite of cutting every weak sentence. \"Hesitation\" means reluctance to act, but the editor acts decisively. \"Warmth\" means friendliness and does not describe the demanding strictness the sentence praises." },
  { id: "t16rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author begins by admitting that the early printing press was crude and slow, then argues that these very flaws pushed inventors toward the refinements that made printing fast and cheap.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It reframes early shortcomings as the spur for later improvements.", "It denies the early press had any flaws.", "It claims printing never improved.", "It lists the prices of printed books."], correct: 0, explanation: "The answer is choice A. The author's reasoning is that the early press's flaws (\"crude and slow\") were the very thing that \"pushed inventors toward the refinements\" — that is, the shortcomings became the spur for later improvements, exactly what choice A states. Choice B (\"denies the early press had any flaws\") contradicts the author's admission that it was crude and slow. Choice C (\"printing never improved\") contradicts the statement that the refinements \"made printing fast and cheap.\" Choice D (\"lists the prices of printed books\") is off topic; no such prices appear." },
  { id: "t16rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having studied the river for a decade ______ the scientist could predict the timing of each year's flood almost to the day.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the timing of each year's flood was predictable", "the scientist could predict the timing of each year's flood", "predicting the flood was easy each year", "it became easy to predict the flood's timing"], correct: 1, explanation: "The answer is choice B. The rule: an introductory participial phrase (\"Having studied the river for a decade\") must modify the noun immediately after it, and only a person can have studied the river. Choice B places \"the scientist\" right after the phrase, so the scientist did the studying — correct. Choice A makes \"the timing\" the subject, illogically implying the timing studied the river (a dangling modifier). Choice C makes \"predicting the flood\" the subject, again something that cannot study a river. Choice D makes the dummy subject \"it\" do the studying, which is equally illogical." },
  { id: "t16rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine produced strong immunity in laboratory mice. ______, the response in human volunteers proved weaker and shorter-lived.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In human trials, however", "For this reason", "Similarly"], correct: 1, explanation: "The answer is \"In human trials, however.\" The first sentence reports a strong result in mice and the second reports a weaker, shorter-lived response in humans, so a contrast transition is needed, and \"however\" signals exactly that opposition while \"In human trials\" specifies the shift in subjects. \"Consequently\" implies the weaker human response was caused by the strong mouse result, which is illogical. \"For this reason\" likewise signals cause-effect, not contrast. \"Similarly\" signals likeness, but the two results differ rather than match." },
  { id: "t16rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, in which a quiet opening motif returns, fully transformed, in the triumphant finale.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "fragmented", "arbitrary", "monotonous"], correct: 0, explanation: "The answer is \"cohesive.\" The detail \"a quiet opening motif returns, fully transformed, in the triumphant finale\" describes elements that connect and unify the symphony, which is what \"cohesive\" (well-integrated, holding together) means. \"Fragmented\" means broken into disconnected pieces, the opposite of a unifying motif. \"Arbitrary\" means random and unplanned, which contradicts the deliberate return of the motif. \"Monotonous\" means tediously unvarying, but the motif returns \"transformed,\" so the design has variety, not dull sameness." },
  { id: "t16rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across six schools, those that added a free breakfast program saw attendance rise by an average of 9%, while schools without the program saw no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding free breakfast was associated with higher attendance.", "Free breakfast lowered attendance.", "School policy had no relationship to attendance.", "Every school added the breakfast program."], correct: 0, explanation: "The answer is choice A. The data state that schools adding a free breakfast program saw attendance rise by an average of 9%, while schools without it \"saw no change,\" so adding free breakfast was associated with higher attendance — a careful, correlation-level claim that choice A makes. Choice B (\"lowered attendance\") reverses the direction of the effect. Choice C (\"no relationship\") contradicts the clear difference between the two groups. Choice D (\"every school added the program\") overgeneralizes, since the text describes only some schools adding it." },
  { id: "t16rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The composer's early sketches — hurried, fragmentary, but unmistakably original ______ already hint at the masterpieces to come.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["original —", "original,", "original", "original;"], correct: 0, explanation: "The answer is \"original —\" with a dash. The rule: punctuation marks that set off an interrupting element must be paired and matched; the sentence opens the interruption with a dash before \"hurried,\" so it must close with a dash after \"original.\" \"Original,\" with a comma mismatches the opening dash. \"Original\" with no punctuation fails to close the interrupting phrase, leaving the sentence's main clause unmarked. \"Original;\" with a semicolon mismatches the opening dash and wrongly suggests a clause boundary." },
  { id: "t16rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The board dismissed the engineer's caution as ______, only to see the very failure she had warned of strike within the year.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overcautious", "prophetic", "justified", "sensible"], correct: 0, explanation: "The answer is \"overcautious.\" The board \"dismissed\" the engineer's caution, so the blank must be a dismissive, negative judgment; calling a warning \"overcautious\" (excessively careful, worrying needlessly) is exactly such a dismissal — made ironic because the warned-of failure then struck. \"Prophetic\" means accurately predicting the future, which praises the warning rather than dismisses it. \"Justified\" means well-founded, again crediting the warning. \"Sensible\" means reasonable, also a compliment, so none of these three fits the dismissive sense required." },
  { id: "t16rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One critic blames the film's failure on its confusing plot; another blames its weak marketing. A third suggests that the two problems fed each other.", prompt: "Which choice best describes the third critic's position?", type: "mcq", choices: ["The plot and marketing problems worked together to cause the failure.", "Neither the plot nor the marketing mattered.", "Only the plot was to blame.", "The film did not actually fail."], correct: 0, explanation: "The answer is choice A. The third critic \"suggests that the two problems fed each other,\" meaning the confusing plot and the weak marketing reinforced one another to cause the failure — exactly what choice A states. Choice B (\"neither mattered\") denies both causes, contradicting the critic, who blames both. Choice C (\"only the plot\") names just one cause, but the third critic ties the two together. Choice D (\"the film did not actually fail\") contradicts the shared premise that the film failed." },
  { id: "t16rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The pilots rerouted the flight ______ a sudden storm had closed the original airport.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["flight, a", "flight; a", "flight a", "flight: a"], correct: 1, explanation: "The answer is \"flight; a\" with a semicolon. The rule: a semicolon joins two related independent clauses, and both \"The pilots rerouted the flight\" and \"a sudden storm had closed the original airport\" are complete clauses, so the semicolon is correct. \"Flight, a\" joins two independent clauses with only a comma, a comma splice. \"Flight a\" runs them together with no punctuation, a run-on. \"Flight: a\" misuses a colon, which introduces a list or explanation; here the second clause states a separate fact, not an elaboration that a colon would signal." },
  { id: "t16rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the new law's burdens fell unequally. ______, large firms absorbed the costs easily while small shops struggled to comply.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The answer is \"Specifically.\" The first sentence makes a general point (the law's burdens fell unequally) and the second gives the concrete detail behind it (large firms coped easily while small shops struggled), so a transition that introduces a specific illustration is needed, and \"Specifically\" does that. \"In contrast\" signals opposition, but the second sentence supports the first rather than opposing it. \"Nevertheless\" signals a concession against the prior point, which is not the relationship here. \"Otherwise\" suggests an alternative outcome, which the supporting detail is not." },
  { id: "t16rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying up every thread, the series finale leaves several mysteries ______, inviting fans to debate them for years.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "settled", "trivial", "explained"], correct: 0, explanation: "The answer is \"unresolved.\" The phrase \"Rather than tying up every thread\" tells us the finale leaves things unfinished, and \"inviting fans to debate them for years\" confirms the mysteries stay open — which is what \"unresolved\" means. \"Settled\" means concluded or decided, the opposite of leaving threads untied. \"Explained\" likewise means resolved, contradicting \"rather than tying up every thread.\" \"Trivial\" means unimportant, but mysteries that fans \"debate for years\" are clearly significant, so it misdescribes them." },
  { id: "t16rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that his survey reached only one neighborhood, but he argues that the pattern it revealed was so striking that it warrants a citywide study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["He admits a limitation while defending the result's importance.", "He claims his survey covered the whole city.", "He abandons his finding entirely.", "He argues no further study is needed."], correct: 0, explanation: "The answer is choice A. The author's reasoning has two parts: he \"concedes that his survey reached only one neighborhood\" (admitting a limitation) but \"argues that the pattern…warrants a citywide study\" (defending the result's importance) — exactly the move choice A describes. Choice B (\"covered the whole city\") contradicts his concession that it reached only one neighborhood. Choice C (\"abandons his finding entirely\") reverses his defense of the finding. Choice D (\"no further study is needed\") contradicts his explicit call for a citywide study." },
];

// ─────────────────────── PRACTICE TEST 16 · MATH M1 (22) ─────────────────────
const T16_M_M1: SatQuestion[] = [
  { id: "t16m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve 5x + 8 = 43 for x. Start with the equation: 5x + 8 = 43. Subtract 8 from both sides to undo the addition: 5x = 43 - 8, so 5x = 35. Divide both sides by 5 to undo the multiplication: x = 35 / 5 = 7. Check: substitute back, 5(7) + 8 = 35 + 8 = 43, which matches the original equation. Trap: dividing by 5 before subtracting the 8 (computing 43/5 = 8.6) ignores order of operations in reverse; the added constant must be removed first." },
  { id: "t16m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A printer prints 4 pages every 5 seconds. How many pages does it print in 30 seconds?", type: "mcq", choices: ["24", "20", "28", "30"], correct: 0, explanation: "Goal: find how many pages print in 30 seconds at 4 pages per 5 seconds. Set up a proportion: 4 pages / 5 seconds = p pages / 30 seconds. One way: find the unit rate, 4 / 5 = 0.8 pages per second, then multiply by 30: 0.8 * 30 = 24 pages, which is choice A. Equivalently, 30 seconds is 30/5 = 6 intervals of 5 seconds, and 6 * 4 = 24. Check: 24 pages / 30 seconds = 0.8 pages/second, matching the given rate. Trap: dividing 30 by 5 to get 6 and stopping there gives the number of 5-second intervals, not the pages, and forgets to multiply by the 4 pages printed in each interval." },
  { id: "t16m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² + 2, what is the value of f(4)?", type: "mcq", choices: ["50", "38", "14", "26"], correct: 0, explanation: "Goal: evaluate f(x) = 3x² + 2 at x = 4. Substitute 4 for x: f(4) = 3(4)² + 2. By order of operations, do the exponent first: 4² = 16. Then multiply: 3 * 16 = 48. Then add: 48 + 2 = 50, which is choice A. Check: the squaring and multiplication were done before the addition, and 48 + 2 = 50. Trap: computing (3·4)² = 12² = 144 multiplies before squaring, violating order of operations; the exponent applies only to x, not to 3x." },
  { id: "t16m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 18. What is its radius?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the radius of a circle whose diameter is 18. The radius is always half the diameter: r = d / 2. Substitute: r = 18 / 2 = 9. Check: a radius of 9 doubles to a diameter of 2 * 9 = 18, matching the given value. Trap: doubling the diameter (18 * 2 = 36) confuses the relationship; the radius is smaller than the diameter, not larger." },
  { id: "t16m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 3x + 5 passes through the point (4, k). What is the value of k?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find k, the y-value on y = 3x + 5 when x = 4. Since (4, k) is on the line, substitute x = 4: k = 3(4) + 5. By order of operations, multiply first: 3 * 4 = 12. Then add: 12 + 5 = 17, so k = 17. Check: the point (4, 17) gives 3(4) + 5 = 17, satisfying the line's equation. Trap: adding before multiplying (4 + 5 = 9, then 3 * 9 = 27) violates order of operations; the slope multiplies only x, not x + 5." },
  { id: "t16m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: find x so that the mean of 6, 10, and x is 9. The mean of three numbers is their sum divided by 3, so set up (6 + 10 + x) / 3 = 9. Multiply both sides by 3 to clear the denominator: 6 + 10 + x = 27, which simplifies to 16 + x = 27. Subtract 16 from both sides: x = 27 - 16 = 11, choice A. Check: (6 + 10 + 11) / 3 = 27 / 3 = 9, the required mean. Trap: dividing 9 by 3 to get 3, or otherwise treating the mean as if it applied to a single term, misuses the formula; the mean is set equal to the whole sum over 3." },
  { id: "t16m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 7 = 22, what is the value of x?", type: "mcq", choices: ["5", "15", "29", "7"], correct: 0, explanation: "Goal: solve 3x + 7 = 22 for x. Start with 3x + 7 = 22. Subtract 7 from both sides to undo the addition: 3x = 22 - 7 = 15. Divide both sides by 3 to undo the multiplication: x = 15 / 3 = 5, choice A. Check: 3(5) + 7 = 15 + 7 = 22, matching the equation. Trap: choice B (15) is the value of 3x after subtracting 7 but stops before dividing by 3, reporting the intermediate result rather than x." },
  { id: "t16m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the sum of the solutions to x² − 9x + 20 = 0. Factor the quadratic: find two numbers that multiply to 20 and add to -9, namely -4 and -5, so x² - 9x + 20 = (x - 4)(x - 5) = 0. Set each factor to zero: x = 4 or x = 5. Add the roots: 4 + 5 = 9. Check: this matches the shortcut sum of roots = -b/a = -(-9)/1 = 9. Trap: reporting 20 uses the product of the roots (c/a) instead of the sum; the question asks for the sum, not the product." },
  { id: "t16m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A jacket's price rose from $40 to $50. What was the percent increase?", type: "mcq", choices: ["25%", "20%", "10%", "125%"], correct: 0, explanation: "Goal: find the percent increase from $40 to $50. Percent increase = (change / original) * 100. The change is 50 - 40 = 10. Divide by the original (not the new) price: 10 / 40 = 0.25. Multiply by 100: 0.25 * 100 = 25%, choice A. Check: increasing 40 by 25% gives 40 * 1.25 = 50, the new price. Trap: dividing by the new price, 10 / 50 = 0.20 = 20%, gives choice B; percent increase must always be measured against the original amount." },
  { id: "t16m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 85°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["50"], explanation: "Goal: find the third angle of a triangle whose other two angles are 45° and 85°. The angles of any triangle sum to 180°, so third = 180 - 45 - 85. Compute step by step: 180 - 45 = 135, then 135 - 85 = 50, so the third angle is 50°. Check: 45 + 85 + 50 = 180, confirming the angle sum. Trap: subtracting from 90 instead of 180 (treating the angles as complementary) gives a wrong value; only right-angle pairs sum to 90, while the full triangle sums to 180." },
  { id: "t16m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A gym charges a $25 sign-up fee plus $15 per month. Which equation gives the total cost C for m months?", type: "mcq", choices: ["C = 15m + 25", "C = 25m + 15", "C = 40m", "C = 15m − 25"], correct: 0, explanation: "Goal: model total cost C for m months given a $25 one-time fee and $15 per month. The monthly charge accrues with each month, so it multiplies m: 15m. The sign-up fee is paid once regardless of months, so it is the constant: +25. Combining gives C = 15m + 25, choice A. Check: for 1 month, C = 15(1) + 25 = 40, which is the $15 month plus the $25 fee. Trap: choice B (C = 25m + 15) swaps the roles, wrongly charging the $25 every month and the $15 once; the per-month rate must be the coefficient of m." },
  { id: "t16m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 2) = x² + bx − 10, what is the value of b?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find b, the coefficient of x, after expanding (x + 5)(x − 2). Use FOIL: First x*x = x²; Outer x*(-2) = -2x; Inner 5*x = 5x; Last 5*(-2) = -10. Combine the middle terms: -2x + 5x = 3x. So (x + 5)(x - 2) = x² + 3x - 10, and matching to x² + bx - 10 gives b = 3. Check: the constant -10 matches, confirming the expansion. Trap: adding 5 and 2 to get 7 ignores the negative sign on the -2; the inner and outer products are 5x and -2x, which combine to 3x, not 7x." },
  { id: "t16m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 300 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["120", "40", "150", "75"], correct: 0, explanation: "Goal: find how many of 300 people preferred coffee given 40% did. Convert the percent to a decimal: 40% = 40/100 = 0.40. Multiply by the total: 0.40 * 300 = 120, choice A. Check: 120 out of 300 is 120/300 = 0.40 = 40%, matching the survey result. Trap: choice B (40) simply repeats the percent value rather than computing the count of people; the percent must be applied to the 300-person total." },
  { id: "t16m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 1) = 3x + 7, what is the value of x?", type: "mcq", choices: ["6", "4", "3", "8"], correct: 0, explanation: "Goal: solve 5(x − 1) = 3x + 7 for x. First distribute the 5 over both terms inside the parentheses: 5x - 5 = 3x + 7. Subtract 3x from both sides to gather x-terms: 2x - 5 = 7. Add 5 to both sides: 2x = 12. Divide by 2: x = 6, choice A. Check: 5(6 - 1) = 5(5) = 25, and 3(6) + 7 = 18 + 7 = 25, so both sides equal 25. Trap: forgetting to distribute the 5 to the -1 (writing 5x - 1 = 3x + 7) drops a -4 and yields the wrong x; the 5 must multiply every term inside the parentheses." },
  { id: "t16m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 9 and width 5. What is its perimeter?", type: "mcq", choices: ["28", "45", "14", "32"], correct: 0, explanation: "Goal: find the perimeter of a rectangle with length 9 and width 5. The perimeter is the total distance around: P = 2(length + width). Substitute: P = 2(9 + 5). Add inside the parentheses first: 9 + 5 = 14. Then multiply: 2 * 14 = 28, choice A. Check: adding all four sides, 9 + 5 + 9 + 5 = 28, confirms the result. Trap: choice B (45) is the area, length * width = 9 * 5 = 45; perimeter measures distance around, not the enclosed region." },
  { id: "t16m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve 3^(x−1) = 27 for x. Rewrite the right side as a power of the same base 3: 27 = 3 * 3 * 3 = 3³. The equation becomes 3^(x-1) = 3³. With equal bases, the exponents must be equal: x - 1 = 3. Add 1 to both sides: x = 4. Check: 3^(4-1) = 3³ = 27, matching the equation. Trap: setting x - 1 = 27 treats the right side as the exponent itself, ignoring that 27 must first be rewritten as a power of 3 before equating exponents." },
  { id: "t16m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "180", "35"], correct: 0, explanation: "Goal: convert 5 map inches to miles using 1 inch = 30 miles. Set up the proportion: 1 inch / 30 miles = 5 inches / d miles, so d = 5 * 30. Multiply: 5 * 30 = 150 miles, choice A. Check: 150 miles / 30 miles-per-inch = 5 inches, matching the map distance. Trap: choice D (35) adds 5 and 30 instead of multiplying; a scale relates the two quantities by multiplication, not addition." },
  { id: "t16m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope of the line through (2, 3) and (6, 15). Slope = (y2 - y1) / (x2 - x1), the change in y over the change in x. Substitute: (15 - 3) / (6 - 2). Compute numerator and denominator: 12 / 4 = 3, so the slope is 3. Check: moving from x = 2 to x = 6 is +4 in x, and 4 * 3 = 12, which matches the rise from y = 3 to y = 15. Trap: inverting the formula to (x2 - x1) / (y2 - y1) = 4/12 = 1/3 computes run over rise instead of rise over run." },
  { id: "t16m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 5x − 2, what value of x makes f(x) = 23?", type: "mcq", choices: ["5", "7", "4", "6"], correct: 0, explanation: "Goal: find x where f(x) = 5x − 2 equals 23. Set up the equation: 5x - 2 = 23. Add 2 to both sides to undo the subtraction: 5x = 25. Divide both sides by 5: x = 5, choice A. Check: f(5) = 5(5) - 2 = 25 - 2 = 23, matching the target. Trap: forgetting to add the 2 back (computing 23 / 5 = 4.6) skips undoing the -2; the constant must be cleared before dividing by 5." },
  { id: "t16m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 8. What is its area, in terms of π?", type: "mcq", choices: ["64π", "16π", "8π", "32π"], correct: 0, explanation: "Goal: find the area of a circle with radius 8, in terms of π. The area formula is A = πr². Substitute r = 8: A = π(8²). Square the radius: 8² = 64. So A = 64π, choice A. Check: the radius is squared (not doubled), and 8 * 8 = 64, giving 64π. Trap: choice B (16π) comes from the circumference formula 2πr = 2π(8) = 16π; area uses r², not 2r." },
  { id: "t16m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 2x + y = 17 and y = 5, what is the value of x?", type: "mcq", choices: ["6", "5", "12", "11"], correct: 0, explanation: "Goal: find x given 2x + y = 17 and y = 5. Substitute y = 5 into the first equation: 2x + 5 = 17. Subtract 5 from both sides: 2x = 12. Divide by 2: x = 6, choice A. Check: 2(6) + 5 = 12 + 5 = 17, matching the equation, and y = 5 is given. Trap: choice C (12) is the value of 2x after subtracting 5 but stops before dividing by 2, reporting the intermediate result instead of x." },
  { id: "t16m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 40-hour week?", type: "grid", gridAnswers: ["880"], explanation: "Goal: find weekly earnings at $22 per hour for 40 hours. Earnings = rate * hours = 22 * 40. Compute: 22 * 40 = 880, so the worker earns $880. Check: 22 * 4 = 88, and 88 * 10 = 880, confirming the product. Trap: adding 22 and 40 to get 62 uses the wrong operation; pay is the hourly rate multiplied by the number of hours, not their sum." },
];

